function buildCommand() {
  const __args = [['ping'], 'Owner', 'Check response speed', async ({ sock, from, msg, cfg }) => {
  const start = Date.now();
  const sent = await sock.sendMessage(from, { text: 'Pinging...' }, { quoted: msg });
  const ms = Date.now() - start;
  const speedBar = progressBar(Math.min(100, Math.round((200 - Math.min(ms, 200)) / 2)));
  await sock.sendMessage(from, {
    text:
`┌「 ⚡ *${cfg.botName}* 」
│ ${ms}ms ${speedBar}
└─ ${cfg.botName}`,
    edit: sent.key
  });
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
